INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1014, '数学', '三年级', 'fill', 2, '{"stem": "填空(3)：在括号里填入>、<或=：4×70（=）40×7；500×4（<）500×6；300×9（=）9×300；400×20（>）60×4；600×5（>）20×40；6×300（=）... "}', '=, <, =, >, >', '4×70=280=40×7; 500×4=2000<500×6=3000; 300×9=2700=9×300; 400×20=8000>60×4=240; 600×5=3000>20×40=800', 'jsj3_sx_v97', '["jsj3_sx","U2","p018","fill_03"]', 1, NULL);
