INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1014, '数学', '三年级', 'single', 2, '{"stem": "选择(3)：一条直跑道长400米，小明每天沿跑道跑4个来回，他每天跑（ ）米。A. 1600  B. 800  C. 3200"}', 'C', '1个来回=2×400=800米, 4个来回=800×4=3200米', 'jsj3_sx_v97', '["jsj3_sx","U2","p018","choice_03"]', 1, NULL);
