INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1014, '数学', '三年级', 'apply', 2, '{"stem": "应用(1)：三年级平均每个班有40名学生，6个班一共有多少名学生？（4分）"}', '240（名）', '40×6=240（名）', 'jsj3_sx_v97', '["jsj3_sx","U2","p019","apply_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1014, '数学', '三年级', 'apply', 2, '{"stem": "应用(2)：欢欢同学参加1000米跑步比赛，她跑了3圈，已经跑了多少米？还剩多少米？（4分）一圈跑道长300米。"}', '900（米），100（米）', '3×300=900（米），1000-900=100（米）', 'jsj3_sx_v97', '["jsj3_sx","U2","p019","apply_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1014, '数学', '三年级', 'apply', 2, '{"stem": "应用(3)：一根绳子，被剪成4段长度为50厘米的短绳，还剩20厘米，绳子原来长多少厘米？（4分）"}', '220（厘米）', '4×50=200（厘米），200+20=220（厘米）', 'jsj3_sx_v97', '["jsj3_sx","U2","p019","apply_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1014, '数学', '三年级', 'apply', 2, '{"stem": "应用(4)：一只狮子重300千克，一头河马比7只狮子还重150千克，一头河马重多少千克？（4分）"}', '2250（千克）', '300×7=2100（千克），2100+150=2250（千克）', 'jsj3_sx_v97', '["jsj3_sx","U2","p019","apply_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1014, '数学', '三年级', 'apply', 2, '{"stem": "应用(5)：爸爸的钱包里有4张50元和5张100元的人民币，他的钱包里一共有多少元？（5分）"}', '700（元）', '4×50=200（元），5×100=500（元），200+500=700（元）', 'jsj3_sx_v97', '["jsj3_sx","U2","p019","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1013, '数学', '三年级', 'fill', 3, '{"stem": "思维拓展：丽丽今年9岁，妈妈今年43岁，外婆今年72岁，几年后她们三人的年龄和是130岁？（10分）"}', '2（年）', '现在年龄和 9+43+72=124, 需增加 130-124=6, 每过1年三人共增3岁, 6÷3=2（年）', 'jsj3_sx_v97', '["jsj3_sx","U2","p019","think_01"]', 1, NULL);